"""Asset guard qualification using generated bytes; no external calls."""
from dataclasses import replace
from email.message import Message
import hashlib
import http.client
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from tempfile import TemporaryDirectory
from threading import Thread
import unittest

from backend.basemap_assets import Asset, BoundedAssets, REVIEWED_ASSETS
from backend.basemap_limits import ASSET_LIMIT
from backend.basemap_transport import AcquisitionBlocked


DATA = b"generated asset"
ENTRY = Asset("fixture.bin", "assets.example.invalid", "/release/v1/fixture.bin",
              len(DATA), hashlib.sha256(DATA).hexdigest(), "invented test fixture")


class Reply:
    def __init__(self, status=200, body=DATA, length=len(DATA), **headers):
        self.status = status
        self.body = body
        self.headers = Message()
        self.headers["Content-Length"] = str(length)
        for name, value in headers.items():
            self.headers[name.replace("_", "-")] = value
        self.reads = 0

    def read1(self, n):
        self.reads += 1
        data, self.body = self.body[:n], self.body[n:]
        return data

    def close(self):
        pass


class Connection:
    def __init__(self, reply):
        self.reply = reply
        self.calls = []

    def __call__(self, host, timeout):
        self.host = host
        return self

    def request(self, method, path, headers):
        self.calls.append((self.host, method, path, headers))

    def getresponse(self):
        return self.reply

    def close(self):
        pass


class AssetTests(unittest.TestCase):
    def setUp(self):
        self.temp = TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)

    def guard(self, reply=None, manifest=(ENTRY,), **kwargs):
        conn = Connection(reply or Reply())
        return BoundedAssets(self.root, manifest=manifest, _mount_check=lambda p:p,
                             _connection_factory=conn, **kwargs), conn

    def test_empty_live_manifest_blocks_network(self):
        self.assertEqual(REVIEWED_ASSETS, ())
        guard, conn = self.guard(manifest=REVIEWED_ASSETS)
        with self.assertRaisesRegex(AcquisitionBlocked, "asset_not_authorised"):
            guard.fetch(ENTRY.name)
        self.assertEqual(conn.calls, [])

    def test_verified_asset_written_and_not_retried(self):
        guard, conn = self.guard()
        output = guard.fetch(ENTRY.name)
        self.assertEqual(output.read_bytes(), DATA)
        self.assertEqual((guard.reserved_bytes, guard.received_bytes), (len(DATA),len(DATA)))
        self.assertEqual(conn.calls[0][:3], (ENTRY.host,"GET",ENTRY.path))
        with self.assertRaises(AcquisitionBlocked):
            guard.fetch(ENTRY.name)
        self.assertEqual(len(conn.calls), 1)
        self.assertEqual(output.read_bytes(), DATA)

    def test_reject_invalid_manifest_and_total_budget(self):
        for manifest in ((replace(ENTRY,name="../bad"),),
                         (replace(ENTRY,host="https://bad.invalid"),),
                         (replace(ENTRY,path="/x/../y"),),
                         (replace(ENTRY,path="/x?token=foo"),),
                         (replace(ENTRY,sha256=""),),
                         (replace(ENTRY,notice=""),),
                         (replace(ENTRY,size=ASSET_LIMIT+1),),
                         (ENTRY,ENTRY)):
            with self.subTest(manifest=manifest):
                with self.assertRaisesRegex(AcquisitionBlocked, "asset_manifest_invalid"):
                    self.guard(manifest=manifest)
        with self.assertRaises(AcquisitionBlocked):
            self.guard(_byte_limit=len(DATA)-1)

    def test_reject_redirect_bad_length_encoding_before_body(self):
        for reply in (Reply(status=302),Reply(status=206),Reply(length=len(DATA)+1),
                      Reply(Content_Encoding="gzip"),Reply(Transfer_Encoding="chunked")):
            with self.subTest(status=reply.status):
                guard, conn = self.guard(reply)
                with self.assertRaises(AcquisitionBlocked):
                    guard.fetch(ENTRY.name)
                self.assertEqual(reply.reads,0)
                self.assertEqual(guard.reserved_bytes,len(DATA))
                self.assertEqual(list(self.root.iterdir()),[])
                with self.assertRaises(AcquisitionBlocked):
                    guard.fetch(ENTRY.name)
                self.assertEqual(len(conn.calls),1)

    def test_partial_and_digest_failure_cleanup(self):
        for body in (DATA[:3], b"x"*len(DATA)):
            guard, _ = self.guard(Reply(body=body))
            with self.assertRaises(AcquisitionBlocked):
                guard.fetch(ENTRY.name)
            self.assertEqual(guard.received_bytes,len(body))
            self.assertEqual(guard.reserved_bytes,len(DATA))
            self.assertEqual(list(self.root.iterdir()),[])

    def test_no_overwrite_or_symlink_target(self):
        target = self.root/ENTRY.name
        target.write_bytes(b"existing")
        guard, conn = self.guard()
        with self.assertRaises(AcquisitionBlocked):
            guard.fetch(ENTRY.name)
        self.assertEqual(target.read_bytes(),b"existing")
        target.unlink()
        target.symlink_to(self.root/"absent")
        guard, conn = self.guard()
        with self.assertRaises(AcquisitionBlocked):
            guard.fetch(ENTRY.name)
        self.assertEqual(conn.calls,[])
        self.assertTrue(target.is_symlink())

    def test_deadline_prevents_contact(self):
        now = [0]
        guard, conn = self.guard(_clock=lambda:now[0],_seconds=1)
        now[0]=2
        with self.assertRaisesRegex(AcquisitionBlocked,"asset_deadline_exhausted"):
            guard.fetch(ENTRY.name)
        self.assertEqual(conn.calls,[])

    def test_actual_loopback_http_asset(self):
        calls=[]
        class Handler(BaseHTTPRequestHandler):
            def log_message(self,*args): pass
            def do_GET(self):
                calls.append(self.path)
                self.send_response(200)
                self.send_header("Content-Length",str(len(DATA)))
                self.end_headers()
                self.wfile.write(DATA)
        server=HTTPServer(("127.0.0.1",0),Handler)
        thread=Thread(target=server.serve_forever,daemon=True)
        thread.start()
        try:
            guard=BoundedAssets(self.root,manifest=(ENTRY,),_mount_check=lambda p:p,
                _connection_factory=lambda host,timeout:http.client.HTTPConnection(
                    "127.0.0.1",server.server_port,timeout=timeout))
            self.assertEqual(guard.fetch(ENTRY.name).read_bytes(),DATA)
            self.assertEqual(calls,[ENTRY.path])
        finally:
            server.shutdown()
            server.server_close()
            thread.join()
